import subprocess
import difflib

def get_blob(stage, path):
    try:
        return subprocess.check_output([b'git', b'show', b':%d:%s' % (stage, path)], stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError:
        return None

def analyze(base, side):
    base_lines = base.splitlines(keepends=True) if base is not None else []
    side_lines = side.splitlines(keepends=True) if side is not None else []
    actions = [None] * len(base_lines)
    inserts = [[] for _ in range(len(base_lines) + 1)]
    sm = difflib.SequenceMatcher(None, base_lines, side_lines, autojunk=False)
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'equal':
            continue
        if tag == 'replace':
            blen = i2 - i1
            slen = j2 - j1
            m = min(blen, slen)
            for k in range(m):
                actions[i1 + k] = ('replace', side_lines[j1 + k:j1 + k + 1])
            for k in range(m, blen):
                actions[i1 + k] = ('delete', None)
            if slen > m:
                inserts[i2].extend(side_lines[j1 + m:j2])
        elif tag == 'delete':
            for i in range(i1, i2):
                actions[i] = ('delete', None)
        elif tag == 'insert':
            inserts[i1].extend(side_lines[j1:j2])
    return actions, inserts

out = subprocess.check_output([b'git', b'diff', b'--name-only', b'-z', b'--diff-filter=U'])
paths = [p for p in out.split(b'\0') if p]
for path in paths:
    base = get_blob(1, path)
    local = get_blob(2, path)
    upstream = get_blob(3, path)
    if local is None or upstream is None:
        subprocess.check_call([b'git', b'rm', b'-f', b'--', path])
        continue
    la, li = analyze(base, local)
    ua, ui = analyze(base, upstream)
    base_lines = base.splitlines(keepends=True) if base is not None else []
    result = []
    for i in range(len(base_lines) + 1):
        result.extend(li[i])
        result.extend(ui[i])
        if i == len(base_lines):
            break
        la_i = la[i]
        ua_i = ua[i]
        if la_i is not None and la_i[0] == 'delete':
            continue
        if ua_i is not None and ua_i[0] == 'delete':
            continue
        if ua_i is not None and ua_i[0] == 'replace':
            result.extend(ua_i[1])
        elif la_i is not None and la_i[0] == 'replace':
            result.extend(la_i[1])
        else:
            result.append(base_lines[i])
    with open(path, 'wb') as f:
        f.write(b''.join(result))
    subprocess.check_call([b'git', b'add', b'--', path])
